function dump(n, depth){
  if(depth>3) return null;
  const o = {id:n.id, name:n.name, type:n.type, w:n.width, h:n.height};
  if(n.type==="TEXT"){o.chars=n.characters; o.fontName=n.fontName; o.fontSize=n.fontSize; o.fills=JSON.parse(JSON.stringify(n.fills));}
  if("fills" in n && n.type!=="TEXT"){try{o.fills=JSON.parse(JSON.stringify(n.fills));}catch(e){}}
  if("cornerRadius" in n) o.cornerRadius=n.cornerRadius;
  if("children" in n) o.children=n.children.map(c=>dump(c,depth+1)).filter(Boolean);
  return o;
}
