async function T(chars,size,style,color,align){
  const t=figma.createText(); t.fontName={family:"Roboto",style}; t.fontSize=size;
  t.characters=chars; t.fills=solid(color); if(align)t.textAlignHorizontal=align;
  t.name=chars.slice(0,40); return t;
}
function F(name,dir,gap){
  const f=figma.createFrame(); f.name=name; f.layoutMode=dir||"HORIZONTAL";
  f.itemSpacing=gap||0; f.primaryAxisSizingMode="AUTO"; f.counterAxisSizingMode="AUTO";
  f.fills=[]; return f;
}
function circle(d,color){const e=figma.createEllipse();e.resize(d,d);e.fills=solid(color);return e;}
async function inst(id){const n=await figma.getNodeByIdAsync(id);return n.createInstance();}
function mkComp(name,node){const c=figma.createComponentFromNode(node);c.name=name;return c;}
async function iconBtn(iconId,name){const b=F(name,"NONE");b.resize(40,40);b.cornerRadius=20;b.fills=solid(C.surface2);const i=await inst(iconId);i.x=8;i.y=8;b.appendChild(i);return b;}
// safe variant set: convert frames to components first, then combine
function mkSet(name,frames){
  const cs=frames.map(f=>figma.createComponentFromNode(f));
  try{
    const set=figma.combineAsVariants(cs,page);
    set.name=name; set.layoutMode="VERTICAL"; set.itemSpacing=24;
    return set;
  }catch(e){
    // fallback: keep as individual components named name/variant
    for(const c of cs){ c.name=name+"/"+c.name; }
    return {name, fallback:true, children:cs, getVariant(prop){return cs.find(c=>c.name.endsWith(prop));}};
  }
}

