  border:{r:0.169,g:0.192,b:0.247}, hi:{r:0.961,g:0.969,b:0.98}, mid:{r:0.612,g:0.651,b:0.714},
  low:{r:0.42,g:0.455,b:0.514}, brand:{r:0.153,g:0.588,b:0.275}, gain:{r:0.18,g:0.8,b:0.443},
