async function T(chars,size,style,color,align){
  const t=figma.createText(); t.fontName={family:"Roboto",style}; t.fontSize=size;
  t.characters=chars; t.fills=solid(color); if(align)t.textAlignHorizontal=align;
  t.name=chars.slice(0,40); return t;
}
function F(name,dir,gap){
  const f=figma.createFrame(); f.name=name; f.layoutMode=dir||"HORIZONTAL";
  f.itemSpacing=gap||0; f.primaryAxisSizingMode="AUTO"; f.counterAxisSizingMode="AUTO";
  f.fills=[]; return f;
}
