const C = {
  bg:{r:0.055,g:0.067,b:0.094}, surface:{r:0.098,g:0.114,b:0.153}, surface2:{r:0.133,g:0.153,b:0.20},
  border:{r:0.169,g:0.192,b:0.247}, hi:{r:0.961,g:0.969,b:0.98}, mid:{r:0.612,g:0.651,b:0.714},
  low:{r:0.42,g:0.455,b:0.514}, brand:{r:0.153,g:0.588,b:0.275}, gain:{r:0.18,g:0.8,b:0.443},
  loss:{r:1,g:0.357,b:0.357}
};
const solid=(c,o)=>[{type:"SOLID",color:c,opacity:o===undefined?1:o}];
const add=(p,ns)=>{for(const n of ns)p.appendChild(n);};
async function T(chars,size,style,color,align){
  const t=figma.createText(); t.fontName={family:"Roboto",style}; t.fontSize=size;
  t.characters=chars; t.fills=solid(color); if(align)t.textAlignHorizontal=align;
  t.name=chars.slice(0,40); return t;
}
function F(name,dir,gap){
  const f=figma.createFrame(); f.name=name; f.layoutMode=dir||"HORIZONTAL";
  f.itemSpacing=gap||0; f.primaryAxisSizingMode="AUTO"; f.counterAxisSizingMode="AUTO";
  f.fills=[]; return f;
}
async function inst(id){const n=await figma.getNodeByIdAsync(id);return n.createInstance();}
async function node(id){return await figma.getNodeByIdAsync(id);}
function setTxt(root,name,chars){const t=root.findAll(n=>n.name===name&&n.type==="TEXT")[0];if(t)t.characters=chars;return t;}
function mkFrame(name,x,y){
  const f=figma.createFrame(); f.name=name; f.resize(375,812); f.x=x; f.y=y;
  f.layoutMode="VERTICAL"; f.itemSpacing=0; f.fills=solid(C.bg); f.clipsContent=true;
  f.primaryAxisSizingMode="FIXED"; f.counterAxisSizingMode="FIXED";
  page.appendChild(f); return f;
}
async function shellTop(frame){
  const sb=await inst("2:30"); frame.appendChild(sb); sb.layoutAlign="STRETCH";
}
async function shellBottom(frame){
  const hi=await inst("2:40"); frame.appendChild(hi); hi.layoutAlign="STRETCH";
}
function content(frame,gap,pad){
  const c=F("Content","VERTICAL",gap===undefined?16:gap);
  c.paddingLeft=c.paddingRight=pad===undefined?16:pad; c.paddingTop=8; c.paddingBottom=8;
  frame.appendChild(c); c.layoutAlign="STRETCH"; c.layoutGrow=1; c.clipsContent=true;
  return c;
}
// mark40 wrapper components (vector marks inside 40px circle)
const compArea=page.findOne(n=>n.name==="UI Components");
async function mark40(markId,name){
  const w=F(name,"NONE"); w.resize(40,40); w.cornerRadius=20; w.fills=solid(C.surface2);
  const m=await inst(markId); m.resize(24,24); m.x=8; m.y=8; w.appendChild(m);
  const c=figma.createComponentFromNode(w); c.name=name; compArea.appendChild(c);
  return c;
}
