async function dump(id,depth){
  const n=await figma.getNodeByIdAsync(id);
  if(!n)return null;
  const o={id:n.id,name:n.name,type:n.type,w:Math.round(n.width),h:Math.round(n.height)};
  if(n.type==="TEXT")o.chars=n.characters;
  if(depth>0&&"children" in n)o.kids=n.children.map(c=>dump2(c,depth-1));
  return o;
}
