function link(node,target){
  node.reactions=[{trigger:{type:"ON_CLICK"},actions:[{type:"NODE",destinationId:target.id,navigation:"NAVIGATE",transition:{type:"SMART_ANIMATE",duration:0.3,easing:{type:"EASE_IN_AND_OUT"}},resetVideo:false,resetScroll:false}]}];
}

// find helpers
function findByText(f,chars,nameFilter){
  return f.findAll(n=>n.type==="TEXT"&&n.characters===chars&&(!nameFilter||n.name===nameFilter));
}
function ancestorNamed(n,name){let p=n;while(p){if(p.name===name)return p;p=p.parent;}return null;}

const report=[];

// 01: Deposit button -> 04
{
  const dep=findByText(f1,"Deposit")[0];
  const btn=ancestorNamed(dep,"Button/Primary")||ancestorNamed(dep,"ActionBtn")||dep.parent;
  link(btn,f4);report.push("01 Deposit->04:"+btn.name);
}
// 01: tab bar Trending -> 02, Top Up -> 04
{
  const tb=f1.findOne(n=>n.type==="INSTANCE"&&n.name.startsWith("Tab Bar"));
  const items=tb.findAll(n=>n.name==="TabItem");
  // items order: Aktivitas, Trending, TopUp, Pasar, Profil
  link(items[1],f2);link(items[2],f4);
  report.push("01 tabs ok:"+items.length);
}
// 02: GOTO row -> 03
{
  let gotoRow=null;
  for(const r of f2.findAll(n=>n.type==="INSTANCE")){
    const t=r.findOne(n=>n.name==="Ticker"&&n.type==="TEXT");
    if(t&&t.characters==="GOTO")gotoRow=r;
  }
  link(gotoRow,f3);report.push("02 GOTO->03:"+gotoRow.name);
}
// 02: tab bar Aktivitas -> 01, Top Up -> 04
{
  const tb=f2.findOne(n=>n.type==="INSTANCE"&&n.name.startsWith("Tab Bar"));
  const items=tb.findAll(n=>n.name==="TabItem");
  link(items[0],f1);link(items[2],f4);
  report.push("02 tabs ok:"+items.length);
}
// 03: back -> 02
{
  const hdr=f3.findOne(n=>n.type==="INSTANCE"&&n.name.startsWith("Header"));
  const back=hdr.findOne(n=>n.name==="Back"||n.name==="Icon_Back"||n.name==="BackBtn");
  const target=back||hdr;
  link(target,f2);report.push("03 back->02:"+target.name);
}
// 04: Alfamart row -> 05, back -> 01
{
  let alfa=null;
  for(const r of f4.findAll(n=>n.type==="INSTANCE")){
    const t=r.findOne(n=>n.type==="TEXT"&&n.characters==="Alfamart");
    if(t&&r.name.includes("Method"))alfa=r;
  }
  if(!alfa){for(const r of f4.findAll(n=>n.type==="INSTANCE")){const t=r.findOne(n=>n.type==="TEXT"&&n.characters==="Alfamart");if(t)alfa=r;}}
  link(alfa,f5);report.push("04 Alfamart->05:"+alfa.name);
  const hdr=f4.findOne(n=>n.type==="INSTANCE"&&n.name.startsWith("Header"));
  const back=hdr.findOne(n=>n.name==="Back"||n.name==="Icon_Back"||n.name==="BackBtn");
  link(back||hdr,f1);report.push("04 back->01:"+(back?back.name:"hdr"));
}
// 05: Bayar -> 06, back -> 04, Ganti -> 04
{
  const bayar=findByText(f5,"Bayar","Label")[0]||findByText(f5,"Bayar")[0];
  const btn=ancestorNamed(bayar,"Button/Primary")||bayar.parent;
  link(btn,f6);report.push("05 Bayar->06:"+btn.name);
  const hdr=f5.findOne(n=>n.type==="INSTANCE"&&n.name.startsWith("Header"));
  const back=hdr.findOne(n=>n.name==="Back"||n.name==="Icon_Back"||n.name==="BackBtn");
  link(back||hdr,f4);report.push("05 back->04");
  const ganti=findByText(f5,"Ganti")[0];
  link(ganti,f4);report.push("05 Ganti->04");
}
// 06: Oke -> 01
{
  const oke=findByText(f6,"Oke","Label")[0]||findByText(f6,"Oke")[0];
  const btn=ancestorNamed(oke,"Button/Primary")||oke.parent;
  link(btn,f1);report.push("06 Oke->01:"+btn.name);
}
return JSON.stringify(report);

