  if(!node)throw new Error("missing node");
  node.reactions=[{trigger:{type:"ON_CLICK"},actions:[{type:"NODE",destinationId:target.id,navigation:"NAVIGATE",transition:{type:"SMART_ANIMATE",duration:0.3,easing:{type:"EASE_IN_AND_OUT"}}}]}];
}
function findByText(f,chars){return f.findAll(n=>n.type==="TEXT"&&n.characters===chars);}
function ancestorInst(n,re){let p=n;while(p){if(p.type==="INSTANCE"&&re.test(p.name))return p;p=p.parent;}return null;}
